import { lemonSqueezySetup, createCheckout } from '@lemonsqueezy/lemonsqueezy.js';

lemonSqueezySetup({
  apiKey: process.env.LEMONSQUEEZY_API_KEY!,
});

// Create a checkout for a specific variant
const { data, error } = await createCheckout(
  process.env.LEMONSQUEEZY_STORE_ID!, // Your store ID
  process.env.LEMONSQUEEZY_VARIANT_ID!, // The product variant ID
  {
    checkoutOptions: {
      embed: false,
      media: true,
      logo: true,
    },
    checkoutData: {
      email: 'customer@example.com', // Pre-fill customer email
      custom: {
        userId: 'user_123', // Pass through to webhooks
      },
    },
    productOptions: {
      redirectUrl: 'https://yourapp.com/success',
      receiptButtonText: 'Go to Dashboard',
      receiptThankYouNote: 'Thank you for subscribing!',
    },
  }
);

if (error) {
  console.error('Failed to create checkout:', error);
  throw new Error(error.title);
}

const checkoutUrl = data?.data.attributes.url;
console.log('Checkout URL:', checkoutUrl);
