import crypto from 'crypto';
import type { Request, Response } from 'express';

interface LemonSqueezyWebhookPayload {
  meta: {
    event_name: string;
    custom_data?: Record<string, string>;
  };
  data: {
    id: string;
    attributes: Record<string, unknown>;
  };
}

export async function handleLemonSqueezyWebhook(req: Request, res: Response) {
  const rawBody = req.body as string; // Must be raw string before JSON parse
  const signature = req.headers['x-signature'] as string;

  // Verify HMAC-SHA256 signature
  const hmac = crypto.createHmac('sha256', process.env.LEMONSQUEEZY_WEBHOOK_SECRET!);
  const digest = hmac.update(rawBody).digest('hex');

  if (!crypto.timingSafeEqual(Buffer.from(digest), Buffer.from(signature))) {
    console.error('Invalid webhook signature');
    return res.status(401).send('Invalid signature');
  }

  const payload = JSON.parse(rawBody) as LemonSqueezyWebhookPayload;
  const eventName = payload.meta.event_name;
  const eventId = payload.data.id; // Use as idempotency key
  const customData = payload.meta.custom_data;

  switch (eventName) {
    case 'order_created': {
      const order = payload.data.attributes;
      console.log('New order:', eventId, 'status:', order['status']);
      // Deliver digital product or provision access
      if (order['status'] === 'paid') {
        await deliverProduct(customData?.userId, eventId);
      }
      break;
    }
    case 'subscription_created': {
      const subscription = payload.data.attributes;
      console.log('New subscription:', eventId, 'status:', subscription['status']);
      await provisionSubscription(customData?.userId, payload.data.id);
      break;
    }
    case 'subscription_cancelled': {
      console.log('Subscription cancelled:', eventId);
      await scheduleAccessRevocation(customData?.userId);
      break;
    }
    default:
      console.log('Unhandled event:', eventName);
  }

  return res.status(200).json({ received: true, eventId });
}

